import json, glob, os, datetime, collections
LOCAL = datetime.timezone(datetime.timedelta(hours=8))
today = datetime.date(2026,11,1)
byid = collections.defaultdict(list)
for path in glob.glob(os.path.expanduser("~/.claude/projects/*/*.jsonl")):
    with open(path, errors="replace") as f:
        for i,line in enumerate(f):
            if '"usage"' not in line: continue
            try: rec = json.loads(line)
            except: continue
            ts = rec.get("timestamp","")
            try: dt = datetime.datetime.fromisoformat(ts.replace("Z","+00:00"))
            except: continue
            if dt.astimezone(LOCAL).date() != today: continue
            u = (rec.get("message") or {}).get("usage") or {}
            if not isinstance(u,dict): continue
            mid = (rec.get("message") or {}).get("id")
            out = u.get("output_tokens") or 0
            if out:
                byid[mid].append((os.path.basename(path)[:8], rec.get("type"), out, u.get("input_tokens"), u.get("cache_read_input_tokens")))
dups = {k:v for k,v in byid.items() if k and len(v)>1}
print("distinct message ids with output>0:", len(byid))
print("ids appearing >1 time:", len(dups))
n=0
for k,v in dups.items():
    if len(set(x[2] for x in v))>1:
        print("VARIES:", k, v); n+=1
        if n>5: break
print("\nexamples of duplicate ids:")
for k,v in list(dups.items())[:6]:
    print(" ", k, v)
print("\n--- sample raw record with output ---")
for path in glob.glob(os.path.expanduser("~/.claude/projects/*/*.jsonl")):
    with open(path, errors="replace") as f:
        for line in f:
            if '"usage"' not in line: continue
            rec=json.loads(line)
            u=(rec.get("message") or {}).get("usage") or {}
            if (u.get("output_tokens") or 0)>0:
                print(path.split("/")[-2], "| type=", rec.get("type"), "| isSidechain=", rec.get("isSidechain"), "| msg.id=", (rec.get("message") or {}).get("id"), "| reqId=", rec.get("requestId"))
                print(json.dumps({k:rec.get(k) for k in ("timestamp","type","requestId","uuid","parentUuid","isSidechain","userType","version","gitBranch")}, ensure_ascii=False))
                print("usage:", json.dumps(u))
                raise SystemExit
EOF

