cat > /tmp/estimate_input.py <<'PYEOF'
import json, glob, os, datetime, statistics, collections

LOCAL = datetime.timezone(datetime.timedelta(hours=8))
TODAY = datetime.date(2026, 11, 1)

def content_chars(msg):
    c = msg.get("content"); n = 0
    if isinstance(c, str): n += len(c)
    elif isinstance(c, list):
        for b in c:
            if not isinstance(b, dict): n += len(str(b)); continue
            t = b.get("type")
            if t == "text": n += len(b.get("text") or "")
            elif t == "thinking": n += len(b.get("thinking") or "")
            elif t == "tool_use": n += len(b.get("name") or "") + len(json.dumps(b.get("input") or {}, ensure_ascii=False))
            elif t == "tool_result":
                cc = b.get("content")
                if isinstance(cc, str): n += len(cc)
                elif isinstance(cc, list):
                    for x in cc:
                        n += len(x.get("text") or "") if isinstance(x, dict) and x.get("type") == "text" else len(json.dumps(x, ensure_ascii=False))
            else: n += len(json.dumps(b, ensure_ascii=False))
    elif c is not None: n += len(str(c))
    return n

def records(path):
    with open(path, errors="replace") as f:
        for line in f:
            if '"usage"' not in line and '"message"' not in line: continue
            try: yield json.loads(line)
            except Exception: pass

calib = []           # (chars, total_prompt_tokens, cache_share)
today_est = collections.Counter()
today_chars = 0
sess_detail = collections.Counter()

for path in glob.glob(os.path.expanduser("~/.claude/projects/*/*.jsonl")):
    sid = os.path.basename(path)[:8]
    proj = os.path.basename(os.path.dirname(path))
    cum = 0
    for rec in records(path):
        ts = rec.get("timestamp") or ""
        try: dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(LOCAL)
        except Exception: continue
        msg = rec.get("message") or {}
        u = msg.get("usage") if isinstance(msg.get("usage"), dict) else None
        before = cum
        cum += content_chars(msg) + 40
        if not u: continue
        inp = (u.get("input_tokens") or 0)
        cr  = (u.get("cache_read_input_tokens") or 0)
        cw  = (u.get("cache_creation_input_tokens") or 0)
        total_prompt = inp + cr + cw
        if total_prompt > 1000 and before > 500 and dt.date() in (
                datetime.date(2026,10,29), datetime.date(2026,10,30), datetime.date(2026,10,28)):
            calib.append((before, total_prompt, cr / total_prompt))
        if dt.date() == TODAY and rec.get("type") == "assistant":
            sess_detail[(proj, sid, "chars")] += before

if calib:
    ratios = sorted(c / t for c, t, _ in calib if c > 0)
    med = statistics.median(ratios)
    print(f"calibration samples: {len(calib)}")
    print(f"chars per prompt-token (median): {med:.3f}  -> ~{1/med:.3f} tokens/char")
    print(f"ratio quartiles: p25={ratios[len(ratios)//4]:.3f} p50={med:.3f} p75={ratios[3*len(ratios)//4]:.3f}")
    avg_cache = statistics.mean(s for _, _, s in calib)
    print(f"avg cache-read share of prompt: {avg_cache*100:.1f}%")
else:
    med = None

print("\n== today, cumulative prompt chars per session ==")
tot_chars = 0
for (proj, sid, _), v in sorted(sess_detail.items(), key=lambda kv: -kv[1]):
    tot_chars += v
    est = v / med if med else 0
    print(f"  {sid}  prompt-chars={v:>12,}   est prompt tokens ~{est:>12,.0f}")
print(f"  {'TOTAL':6}  prompt-chars={tot_chars:>12,}   est prompt tokens ~{tot_chars/med if med else 0:>12,.0f}")
print(f"\nestimated cache-read portion ~{avg_cache*100 if calib else 0:.0f}%, rest billed as fresh input")
