#!/usr/bin/env python3
"""laneai-usage-proxy —— 给不上报 usage 的中转站补上 input_tokens。

背景
----
laneai.dev 对 deepseek 系列永远返回 input_tokens=0。Claude Code 用它算上下文用量：

    dSn(usage) = input_tokens + cache_creation_input_tokens + cache_read_input_tokens

恒为 0 => 自动压缩永不触发 => 会话一直涨 => 上游在约 256K token 处静默截断历史，
表现为「模型重复上一轮、无视新指令」。

本代理插在 Claude Code 和 laneai.dev 之间，按请求体估算 prompt token 数，
把估算值写回响应的 usage.input_tokens，让 CC 恢复感知上下文用量。

用法
----
    python3 ~/.claude/laneai-usage-proxy.py

然后设置 ANTHROPIC_BASE_URL=http://127.0.0.1:8787

环境变量
--------
    LANEAI_PROXY_PORT    监听端口，默认 8787
    LANEAI_UPSTREAM_HOST 上游主机，默认 laneai.dev
    LANEAI_TOKEN_SAFETY  估算安全系数，默认 1.10（宁可高估、早压缩）
    LANEAI_PROXY_LOG     日志路径，默认 ~/.claude/laneai-proxy.log
"""

import json
import os
import ssl
import sys
import time
import http.client
import http.server
import socketserver

UPSTREAM_HOST = os.environ.get("LANEAI_UPSTREAM_HOST", "laneai.dev")
UPSTREAM_PORT = int(os.environ.get("LANEAI_UPSTREAM_PORT", "443"))
LISTEN_HOST = os.environ.get("LANEAI_PROXY_HOST", "127.0.0.1")
LISTEN_PORT = int(os.environ.get("LANEAI_PROXY_PORT", "8787"))
SAFETY = float(os.environ.get("LANEAI_TOKEN_SAFETY", "1.10"))
LOG_PATH = os.path.expanduser(
    os.environ.get("LANEAI_PROXY_LOG", "~/.claude/laneai-proxy.log")
)

# 中日韩 / 全角标点 / 假名 / 谚文：1 字符约 1 token
_CJK = ((0x3040, 0x30FF), (0x3400, 0x4DBF), (0x4E00, 0x9FFF),
        (0xAC00, 0xD7AF), (0x3000, 0x303F), (0xFF00, 0xFFEF))


def _log(msg):
    try:
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write("%s %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), msg))
    except Exception:
        pass


def _count_text(s):
    """英数符号约 3.8 字符/token，CJK 约 1.5 字符/token。"""
    if not s:
        return 0.0
    cjk = 0
    for ch in s:
        cp = ord(ch)
        for lo, hi in _CJK:
            if lo <= cp <= hi:
                cjk += 1
                break
    return cjk / 1.5 + (len(s) - cjk) / 3.8


def _count_content(c):
    if c is None:
        return 0.0
    if isinstance(c, str):
        return _count_text(c)
    if not isinstance(c, list):
        return _count_text(str(c))
    n = 0.0
    for b in c:
