            pass


class Server(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def main():
    srv = Server((LISTEN_HOST, LISTEN_PORT), Proxy)
    _log("proxy listening on http://%s:%d -> https://%s"
         % (LISTEN_HOST, LISTEN_PORT, UPSTREAM_HOST))
    print("laneai-usage-proxy listening on http://%s:%d  ->  https://%s"
          % (LISTEN_HOST, LISTEN_PORT, UPSTREAM_HOST), flush=True)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
