            if k.lower() in ("content-length", "transfer-encoding", "connection"):
                continue
            self.send_header(k, v)
        self.send_header("Transfer-Encoding", "chunked")
        self.end_headers()

        out_tokens = 0
        try:
            while True:
                line = resp.readline()
                if not line:
                    break
                if line.startswith(b"data:"):
                    raw = line[5:].strip()
                    if raw and raw != b"[DONE]":
                        try:
                            ev = json.loads(raw)
                            typ = ev.get("type")
                            if typ == "message_start":
                                msg = ev.get("message")
                                if isinstance(msg, dict):
                                    _patch_usage(msg, tokens)
                            elif typ == "message_delta":
                                u = ev.get("usage")
                                if isinstance(u, dict):
                                    if "input_tokens" not in u or not u.get("input_tokens"):
                                        u["input_tokens"] = tokens
                                    out_tokens = u.get("output_tokens") or out_tokens
                            line = b"data: " + json.dumps(
                                ev, ensure_ascii=False).encode("utf-8") + b"\n"
                        except Exception:
                            pass
                self._chunk(line)
            self._chunk(b"")
        except (BrokenPipeError, ConnectionResetError):
            pass
        finally:
            _log("stream  est_input=%d  out=%d  ctx~%d"
                 % (tokens, out_tokens, tokens + out_tokens))

    # ---- 非流式 ----
    def _relay_buffered(self, resp, tokens, is_messages):
        try:
            raw = resp.read()
        except Exception as e:
            self._send_simple(502, "read error: %s" % e)
            return

        if is_messages and resp.status == 200 and tokens:
            try:
                obj = json.loads(raw)
                if _patch_usage(obj, tokens):
                    raw = json.dumps(obj, ensure_ascii=False).encode("utf-8")
                    u = obj.get("usage") or {}
                    _log("buffered est_input=%d out=%d ctx~%d"
                         % (tokens, u.get("output_tokens") or 0,
                            tokens + (u.get("output_tokens") or 0)))
            except Exception:
                pass

        self.send_response(resp.status)
        for k, v in resp.getheaders():
            if k.lower() in ("content-length", "transfer-encoding", "connection"):
                continue
            self.send_header(k, v)
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        if raw:
            try:
                self.wfile.write(raw)
            except (BrokenPipeError, ConnectionResetError):
                pass

    # ---- 工具 ----
    def _chunk(self, data):
        if data:
            self.wfile.write(("%X\r\n" % len(data)).encode("ascii") + data + b"\r\n")
        else:
            self.wfile.write(b"0\r\n\r\n")
        self.wfile.flush()

    def _send_simple(self, code, text):
        body = text.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except Exception:
            pass


class Server(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def main():
    srv = Server((LISTEN_HOST, LISTEN_PORT), Proxy)
    _log("proxy listening on http://%s:%d -> https://%s"
         % (LISTEN_HOST, LISTEN_PORT, UPSTREAM_HOST))
    print("laneai-usage-proxy listening on http://%s:%d  ->  https://%s"
          % (LISTEN_HOST, LISTEN_PORT, UPSTREAM_HOST), flush=True)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        srv.server_close()


if __name__ == "__main__":
    main()

