#!/usr/bin/env python3
"""laneai-usage-proxy —— 给不上报 usage 的中转站补上 input_tokens。

背景
----
laneai.dev 对 deepseek 系列永远返回 input_tokens = 0，而 Claude Code 用它算上下文用量：

    dSn(usage) = input_tokens + cache_creation_input_tokens + cache_read_input_tokens

恒为 0 => 自动压缩永不触发 => 会话一直涨 => 上游静默截断历史 =>
表现为「模型重复上一轮的话、无视新指令」。

本代理插在 Claude Code 和 laneai.dev 之间，按请求体估算 prompt token 数，
把估算值写回响应的 usage.input_tokens，让 CC 恢复感知上下文用量并按时自动压缩。

参数标定
--------
默认比例来自对本网关实测的静默截断边界（按 256K 窗口反推）：
  - 英文/代码：978,125 字符触发截断 -> 3.82 字符/token
  - 中文：    325,000 字符触发截断 -> 1.27 字符/token

用法
----
    python3 ~/.claude/laneai-usage-proxy.py

然后把 ANTHROPIC_BASE_URL 指向 http://127.0.0.1:8787

环境变量
--------
    LANEAI_PROXY_PORT      监听端口，默认 8787
    LANEAI_PROXY_HOST      监听地址，默认 127.0.0.1
    LANEAI_UPSTREAM_HOST   上游主机，默认 laneai.dev
    LANEAI_UPSTREAM_PORT   上游端口，默认 443
    LANEAI_ASCII_CPT       英文每 token 字符数，默认 3.82
    LANEAI_CJK_CPT         CJK 每 token 字符数，默认 1.27
    LANEAI_TOKEN_SAFETY    估算安全系数，默认 1.06（略高估，早压缩）
    LANEAI_PROXY_LOG       日志路径，默认 ~/.claude/laneai-proxy.log
    LANEAI_PROXY_VERBOSE   设 1 则每次请求都写日志
"""

import json
import os
import re
import ssl
import time
import http.client
import http.server
import socketserver

UPSTREAM_HOST = os.environ.get("LANEAI_UPSTREAM_HOST", "laneai.dev")
UPSTREAM_PORT = int(os.environ.get("LANEAI_UPSTREAM_PORT", "443"))
LISTEN_HOST = os.environ.get("LANEAI_PROXY_HOST", "127.0.0.1")
LISTEN_PORT = int(os.environ.get("LANEAI_PROXY_PORT", "8787"))

ASCII_CPT = float(os.environ.get("LANEAI_ASCII_CPT", "3.82"))
CJK_CPT = float(os.environ.get("LANEAI_CJK_CPT", "1.27"))
SAFETY = float(os.environ.get("LANEAI_TOKEN_SAFETY", "1.06"))
VERBOSE = os.environ.get("LANEAI_PROXY_VERBOSE", "") not in ("", "0")
LOG_PATH = os.path.expanduser(
    os.environ.get("LANEAI_PROXY_LOG", "~/.claude/laneai-proxy.log")
)

# 中日韩文字、假名、谚文、全角标点
_CJK_RE = re.compile("[぀-ヿ㐀-䶿一-鿿가-힯　-〿＀-￯]")


def _log(msg):
    try:
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write("%s %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), msg))
    except Exception:
        pass


def _count_text(s):
    if not s:
        return 0.0
    cjk = len(_CJK_RE.findall(s))
    return cjk / CJK_CPT + (len(s) - cjk) / ASCII_CPT


def _count_content(c):
    if c is None:
        return 0.0
    if isinstance(c, str):
        return _count_text(c)
    if not isinstance(c, list):
        return _count_text(str(c))
    total = 0.0
    for b in c:
        if not isinstance(b, dict):
            total += _count_text(str(b))
            continue
        t = b.get("type")
        if t == "text":
            total += _count_text(b.get("text") or "")
        elif t == "thinking":
            total += _count_text(b.get("thinking") or "")
        elif t == "tool_use":
            total += _count_text(b.get("name") or "")
            total += _count_text(json.dumps(b.get("input") or {}, ensure_ascii=False))
        elif t == "tool_result":
            total += _count_content(b.get("content"))
        elif t == "image":
            total += 1600.0
        else:
            total += _count_text(json.dumps(b, ensure_ascii=False))
    return total


def estimate_prompt_tokens(payload):
    """估算一次请求的 prompt token 总数（含 system 与 tools）。"""
    total = _count_content(payload.get("system"))
    for t in payload.get("tools") or []:
        total += _count_text(json.dumps(t, ensure_ascii=False)) + 8.0
    for m in payload.get("messages") or []:
        total += 4.0
        total += _count_content(m.get("content"))
    return max(1, int(total * SAFETY))


def _patch_usage(obj, tokens):
    """把估算值写进 obj['usage']['input_tokens']。返回是否改动。"""
    if not isinstance(obj, dict):
        return False
    u = obj.get("usage")
    if not isinstance(u, dict):
        return False
    u["input_tokens"] = tokens
    if not u.get("cache_creation_input_tokens"):
        u["cache_creation_input_tokens"] = 0
    if not u.get("cache_read_input_tokens"):
        u["cache_read_input_tokens"] = 0
    return True


class Handler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "laneai-usage-proxy/1.0"

    def log_message(self, fmt, *args):
        pass

    def do_POST(self):
        self._handle("POST")

    def do_GET(self):
        self._handle("GET")

    def do_HEAD(self):
        self._handle("HEAD")

    def _handle(self, method):
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except (TypeError, ValueError):
            length = 0
        body = self.rfile.read(length) if length else b""

        path_only = self.path.split("?", 1)[0]
        is_messages = path_only.endswith("/v1/messages")

        tokens = 0
        stream = False
        if body and is_messages:
            try:
                payload = json.loads(body)
                tokens = estimate_prompt_tokens(payload)
                stream = bool(payload.get("stream"))
            except Exception as e:
                _log("estimate failed: %r" % (e,))

        hdrs = {}
        for k, v in self.headers.items():
            lk = k.lower()
            if lk in ("host", "connection", "accept-encoding", "content-length"):
                continue
            hdrs[k] = v
        hdrs["Accept-Encoding"] = "identity"
        if body:
            hdrs["Content-Length"] = str(len(body))

        conn = None
        try:
            ctx = ssl.create_default_context()
            conn = http.client.HTTPSConnection(
                UPSTREAM_HOST, UPSTREAM_PORT, timeout=900, context=ctx
            )
            conn.request(method, self.path, body=body or None, headers=hdrs)
            resp = conn.getresponse()
        except Exception as e:
            _log("upstream connect failed: %r" % (e,))
            self._send_simple(502, "upstream error: %s" % e)
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass
            return

        try:
            ctype = (resp.getheader("Content-Type") or "")
            is_sse = "text/event-stream" in ctype
            if is_messages and resp.status == 200 and (stream or is_sse):
                self._relay_stream(resp, tokens)
            else:
                self._relay_buffered(resp, tokens, is_messages)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    def _send_simple(self, code, text):
        data = text.encode("utf-8", "replace")
        self.send_response(code)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        try:
            self.wfile.write(data)
        except Exception:
            pass

    def _relay_buffered(self, resp, tokens, is_messages):
        raw = resp.read()
        if is_messages and resp.status == 200:
            try:
                obj = json.loads(raw)
                if _patch_usage(obj, tokens):
                    raw = json.dumps(obj, ensure_ascii=False).encode("utf-8")
                    if VERBOSE:
                        _log("patched non-stream input_tokens=%d" % tokens)
            except Exception as e:
                _log("non-stream patch failed: %r" % (e,))

        self.send_response(resp.status)
        for k, v in resp.getheaders():
            if k.lower() in ("content-length", "transfer-encoding", "connection"):
                continue
            self.send_header(k, v)
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        try:
            self.wfile.write(raw)
        except Exception:
            pass

    def _relay_stream(self, resp, tokens):
        self.send_response(resp.status)
        for k, v in resp.getheaders():
            if k.lower() in ("content-length", "transfer-encoding", "connection"):
                continue
            self.send_header(k, v)
        self.send_header("Transfer-Encoding", "chunked")
        self.end_headers()

        def write_chunk(payload):
            if not payload:
                return
            self.wfile.write(b"%x\r\n" % len(payload))
            self.wfile.write(payload)
            self.wfile.write(b"\r\n")
            self.wfile.flush()

        patched_start = False
        try:
            while True:
                line = resp.readline()
                if not line:
                    break

                if not line.startswith(b"data:"):
                    write_chunk(line)
                    continue

                raw = line[5:].strip()
                if not raw or raw == b"[DONE]":
                    write_chunk(line)
                    continue

                try:
                    ev = json.loads(raw)
                except Exception:
                    write_chunk(line)
                    continue

                typ = ev.get("type")
                if typ == "message_start":
                    msg = ev.get("message")
                    if _patch_usage(msg, tokens):
                        patched_start = True
                        if VERBOSE:
                            _log("patched stream input_tokens=%d" % tokens)
                        write_chunk(b"data: " + json.dumps(ev, ensure_ascii=False).encode() + b"\n\n")
                        continue
                elif typ == "message_delta":
                    u = ev.get("usage")
                    if isinstance(u, dict) and not u.get("input_tokens"):
                        u["input_tokens"] = tokens
                        write_chunk(b"data: " + json.dumps(ev, ensure_ascii=False).encode() + b"\n\n")
                        continue

                write_chunk(line)
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:
            _log("stream relay error: %r" % (e,))
        finally:
            try:
                self.wfile.write(b"0\r\n\r\n")
                self.wfile.flush()
            except Exception:
                pass
            if VERBOSE and not patched_start:
                _log("warning: message_start not patched")


class ThreadedHTTPServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def main():
    srv = ThreadedHTTPServer((LISTEN_HOST, LISTEN_PORT), Handler)
    _log("listening on %s:%d -> %s:%d" % (LISTEN_HOST, LISTEN_PORT, UPSTREAM_HOST, UPSTREAM_PORT))
    print("laneai-usage-proxy listening on http://%s:%d -> https://%s" % (LISTEN_HOST, LISTEN_PORT, UPSTREAM_HOST))
    print("set ANTHROPIC_BASE_URL=http://%s:%d" % (LISTEN_HOST, LISTEN_PORT))
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nbye")
        srv.shutdown()


if __name__ == "__main__":
    main()

